'use client';

/**
 * @file useComponentTranslator.ts
 * @input InternationalizationContext (via use())
 * @output useComponentTranslator, and registerEnglishFallback re-exported for
 *   the same importers
 * @position Internal translator for Core components. Not exported from the
 *   package; application code uses the public `useTranslator`.
 *
 * Returns the same provider-bound translator as the public hook. The public
 * hook also registers the whole English catalog, because application code may
 * translate any Astryx key; a component instead registers the English for the
 * keys it names, from its generated map:
 *
 *   import {
 *     registerEnglishFallback,
 *     useComponentTranslator,
 *   } from '../i18n/useComponentTranslator';
 *   import english from '../i18n/generated-english/Button/Button.generated';
 *
 *   registerEnglishFallback(english);
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/i18n/useTranslator.ts
 * - /packages/core/src/i18n/englishFallback.ts
 * - /scripts/i18n-english-fallback.mjs
 */

import {use} from 'react';
import {InternationalizationContext} from '@astryxdesign/core/i18n';
import type {TranslatorFn} from '@astryxdesign/core/i18n';

export {registerEnglishFallback} from './englishFallback';

/**
 * Returns the translator bound to the current provider's locale. Keys resolve
 * to English only when the module naming them registered its English.
 */
export function useComponentTranslator(): TranslatorFn {
  const ctx = use(InternationalizationContext);
  return ctx.translate;
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file sharedRealm.ts
 * @input A registered name and its protocol version
 * @output One value per key in the JavaScript realm, shared by every copy of
 *   Core
 * @position Shared runtime state for stores and contexts; no React and no
 *   client directive, so server-safe modules can use it
 */

/**
 * The registered key of a shared value. The version names the value's shape.
 * Change it when a copy built against the old shape cannot read the value.
 * Each copy then keeps its own value.
 */
export function sharedKey(name: string, version: number): symbol {
  return Symbol.for(`@astryxdesign/core/${name}/v${version}`);
}

/**
 * The value under `key` in this JavaScript realm, created on first use. Every
 * copy of Core that asks for the same key gets the same value.
 *
 * The key names the protocol version, so a value found under it has this
 * protocol's shape. `accepts` guards against a key collision: a value it
 * rejects is left in place, and this copy keeps a value of its own.
 */
export function realmValue<T>(
  key: symbol,
  create: () => T,
  accepts: (value: unknown) => boolean = () => true,
): T {
  const realm = globalThis as typeof globalThis & {[key: symbol]: unknown};
  if (Object.hasOwn(realm, key)) {
    const existing = realm[key];
    return accepts(existing) ? (existing as T) : create();
  }
  const value = create();
  realm[key] = value;
  return value;
}
